import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.CLbANrvH.js";const u=JSON.parse('{"title":"Feature Flags","description":"","frontmatter":{"title":"Feature Flags"},"headers":[],"relativePath":"concepts/feature-flags.md","filePath":"concepts/feature-flags.md","lastUpdated":1791849617000}'),n={name:"concepts/feature-flags.md"};function d(l,e,r,o,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="feature-flags" tabindex="-1">Feature Flags <a class="header-anchor" href="#feature-flags" aria-label="Permalink to &quot;Feature Flags&quot;">​</a></h1><p>neuron exposes its full feature set as Cargo features, so the host binary pays compile time + binary size cost only for what it actually uses. Most capabilities have an opt-in feature; <code>candle</code> is enabled by default since it covers the most common case (LLM + ASR + Rerank + Embedding + Vision all on the candle backend).</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Pulls</th><th>Default?</th><th>What it enables</th></tr></thead><tbody><tr><td><code>candle</code></td><td><code>candle-core</code>, <code>candle-nn</code>, <code>candle-transformers</code>, <code>tokenizers</code>, <code>image</code>, <code>base64</code>, <code>safetensors</code></td><td>✅ (default)</td><td>LLM (Qwen/Llama/Phi/Mistral/ChatGLM), ASR (Whisper), Rerank (BGE/mxbai/jina), Embedding (MiniLM), Vision (YOLOv8/RT-DETR/DETR)</td></tr><tr><td><code>flash-attn</code></td><td><code>candle-flash-attn</code> + <code>candle-transformers/flash-attn</code></td><td>—</td><td>FlashAttention for Llama 2/3 + Mistral + Qwen 2/2.5/3/3.5 (CUDA only)</td></tr><tr><td><code>metal</code></td><td><code>candle-core/metal</code> + <code>candle-nn/metal</code> + <code>candle-transformers/metal</code></td><td>—</td><td>Apple Metal GPU acceleration (M1/M2/M3)</td></tr><tr><td><code>cuda</code></td><td><code>candle-core/cuda</code> + <code>candle-nn/cuda</code> + <code>candle-transformers/cuda</code></td><td>—</td><td>NVIDIA CUDA GPU acceleration</td></tr><tr><td><code>chronos2</code></td><td>(re-uses candle)</td><td>—</td><td>Time-series forecasting (Sprint 3 in progress; candle runtime WIP)</td></tr><tr><td><code>voxcpm</code></td><td><code>burn</code>, <code>burn-store</code>, <code>hound</code></td><td>—</td><td>TTS via VoxCpm (burn 0.21)</td></tr><tr><td><code>litert</code></td><td><code>litert-lm</code></td><td>—</td><td>On-device LLM via Google LiteRT-LM subprocess (Gemma 3)</td></tr><tr><td><code>asr-audio</code></td><td><code>symphonia</code>, <code>rubato</code></td><td>—</td><td>MP3 / FLAC / OGG-Vorbis ASR decoding (otherwise WAV only)</td></tr><tr><td><code>mistralrs</code></td><td><code>mistralrs</code> + (re-uses candle)</td><td>—</td><td>LLM via mistral.rs engine (40+ model families)</td></tr><tr><td><code>tract</code></td><td><code>tract-onnx</code>, <code>ndarray</code>, <code>tokenizers</code>, <code>rustfft</code></td><td>—</td><td>Pure-Rust ONNX inference (Laya <code>POST /v1/decisions</code> + own-ONNX SenseVoiceSmall ASR via <code>model.prepped.onnx</code>)</td></tr><tr><td><code>sherpa</code></td><td><code>sherpa-onnx</code></td><td>—</td><td><code>sherpa-onnx</code> official Rust binding (1.13.x). Downloads prebuilt static libs from GitHub releases at build time — no cmake / C++ toolchain on the host. Backs the sherpa-onnx ASR runtime on SenseVoiceSmall.</td></tr></tbody></table><h2 id="build-recipes" tabindex="-1">Build recipes <a class="header-anchor" href="#build-recipes" aria-label="Permalink to &quot;Build recipes&quot;">​</a></h2><h3 id="minimal-development-build" tabindex="-1">Minimal development build <a class="header-anchor" href="#minimal-development-build" aria-label="Permalink to &quot;Minimal development build&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-default-features</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle</span></span></code></pre></div><p>No TTS, no mistralrs, no litert_lm, no chrono2. Just candle for LLM/ASR/Rerank/Embedding/Vision. ~3-4 min cold build.</p><h3 id="production-desktop-tauri-2-flutter-host" tabindex="-1">Production desktop (Tauri 2 / Flutter host) <a class="header-anchor" href="#production-desktop-tauri-2-flutter-host" aria-label="Permalink to &quot;Production desktop (Tauri 2 / Flutter host)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle,voxcpm,asr-audio</span></span></code></pre></div><p>Adds VoxCpm TTS and MP3/FLAC/OGG-Vorbis ASR support. ~5-6 min cold build.</p><h3 id="server-side-inference-high-throughput" tabindex="-1">Server-side inference (high throughput) <a class="header-anchor" href="#server-side-inference-high-throughput" aria-label="Permalink to &quot;Server-side inference (high throughput)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle,mistralrs,asr-audio</span></span></code></pre></div><p>Adds mistralrs (40+ families, PagedAttention, KV cache). ~8-10 min cold build.</p><h3 id="full-kitchen-sink" tabindex="-1">Full kitchen sink <a class="header-anchor" href="#full-kitchen-sink" aria-label="Permalink to &quot;Full kitchen sink&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle,voxcpm,litert,mistralrs,asr-audio,flash-attn,cuda,chronos2</span></span></code></pre></div><p>Everything. ~12-15 min cold build.</p><h3 id="edge-mobile-no-gpu-minimal-binary" tabindex="-1">Edge / mobile (no GPU, minimal binary) <a class="header-anchor" href="#edge-mobile-no-gpu-minimal-binary" aria-label="Permalink to &quot;Edge / mobile (no GPU, minimal binary)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-default-features</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> candle</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optionally: --features candle,litert for on-device LLM</span></span></code></pre></div><h2 id="what-s-not-feature-gated" tabindex="-1">What&#39;s NOT feature-gated <a class="header-anchor" href="#what-s-not-feature-gated" aria-label="Permalink to &quot;What&#39;s NOT feature-gated&quot;">​</a></h2><p>The HTTP surface (axum), the OpenAI / Anthropic wire format, the multi-source model registry, the <code>ApiAdapter</code> dispatch system, the runtime registry pattern, and the trait shapes for all 6 capabilities are <strong>always compiled in</strong>. Only the engine backends are gated by features.</p><p>This is intentional: you can swap engines at runtime (e.g. switch LLM from candle to mistralrs) without recompiling. The feature flag only controls which engines exist as options to choose from.</p><h2 id="runtime-selection-vs-build-time-selection" tabindex="-1">Runtime selection vs build-time selection <a class="header-anchor" href="#runtime-selection-vs-build-time-selection" aria-label="Permalink to &quot;Runtime selection vs build-time selection&quot;">​</a></h2><p>Once you&#39;ve built with certain features, runtime selection picks the specific engine for a given request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Built with: candle,voxcpm,mistralrs</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Runtime:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEURON_LLM_RUNTIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">candle</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # uses candle (available)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEURON_LLM_RUNTIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mistralrs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # uses mistralrs (available)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEURON_LLM_RUNTIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">litert</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # ERROR — litert not built</span></span></code></pre></div><p>If you try to use a runtime that wasn&#39;t built in, you&#39;ll get a clear error at startup: <code>Error: requested runtime &#39;litert&#39; not in this build (built with: candle,voxcpm)</code>.</p><h2 id="ci-recommendations" tabindex="-1">CI recommendations <a class="header-anchor" href="#ci-recommendations" aria-label="Permalink to &quot;CI recommendations&quot;">​</a></h2><ul><li><strong>Default build</strong> (just <code>--features candle</code>): catches 90% of regressions. Fast.</li><li><strong>Full build</strong> (all features): catches feature-flag interactions and feature-specific bugs. Run on every PR but not on every commit.</li></ul><p>Example CI matrix:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">matrix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  features</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                      # minimal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle,voxcpm&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                               # + TTS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle,mistralrs&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                             # + multi-family</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;candle,voxcpm,litert,mistralrs,asr-audio&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # full</span></span></code></pre></div><h2 id="testing-feature-flag-interactions" tabindex="-1">Testing feature flag interactions <a class="header-anchor" href="#testing-feature-flag-interactions" aria-label="Permalink to &quot;Testing feature flag interactions&quot;">​</a></h2><p>Some features are mutually dependent or have specific orderings. Common pitfalls:</p><ul><li><code>flash-attn</code> <strong>requires CUDA</strong> to be useful (the build succeeds on macOS but <code>flash_attn</code> calls will fail at runtime). Always combine with <code>cuda</code>.</li><li><code>mistralrs</code> <strong>implicitly activates candle</strong> because mistral.rs is built on candle-core 0.10.2 internally.</li><li><code>voxcpm</code> <strong>adds burn</strong> as a fresh dependency tree (~3-5 min compile time). If you don&#39;t need TTS, leave it out.</li><li><code>litert</code> <strong>adds <code>litert-lm</code></strong> but you also need the <code>lit</code> binary on <code>PATH</code> at runtime (the Rust crate is a subprocess wrapper, not a self-contained engine).</li></ul><h2 id="compile-time-table" tabindex="-1">Compile time table <a class="header-anchor" href="#compile-time-table" aria-label="Permalink to &quot;Compile time table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature set</th><th>Cold build</th><th>Incremental</th></tr></thead><tbody><tr><td><code>--features candle</code></td><td>3-4 min</td><td>30-60 s</td></tr><tr><td><code>--features candle,voxcpm</code></td><td>5-6 min</td><td>1-2 min</td></tr><tr><td><code>--features candle,mistralrs</code></td><td>8-10 min</td><td>1-3 min</td></tr><tr><td><code>--features candle,voxcpm,litert,mistralrs,asr-audio</code></td><td>10-12 min</td><td>2-3 min</td></tr><tr><td>Full kitchen sink (+ <code>flash-attn,cuda,chronos2</code>)</td><td>12-15 min</td><td>2-4 min</td></tr></tbody></table><p>These numbers are approximate and depend heavily on host machine (CPU, RAM, SSD). On a fast machine with <code>sccache</code> enabled, cold builds can drop by 30-50%.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/neuron/concepts/engines">Engine Selection</a> — when to use which engine</li><li><a href="/neuron/guide/quick-start">Quick Start</a> — minimal embed example</li><li><a href="/neuron/concepts/architecture">Architecture</a> — how the data flow wires registries to handlers</li></ul>`,38)])])}const k=t(n,[["render",d]]);export{u as __pageData,k as default};
